// SourceEntry One entry of a source listing: its path relative to the source root, and whether it is a directory. The host lists names only and reads no content, so an entry carries no bytes.
type SourceEntry struct {
	// Path The entry's path relative to the source root, slash-separated (for example Chart.yaml or templates/deployment.yaml).
	Path string `json:"path" yaml:"path" cbor:"path"`
	// IsDir Whether the entry is a directory. A guest that resolves a chart root or a single source file among the listing reads this to distinguish directories from files without touching the filesystem.
	IsDir bool `json:"is_dir" yaml:"is_dir" cbor:"is_dir"`
}

// SourceListing The generic enumeration of an acquired source the host hands a sourced provider guest: the source root, whether that root is a directory, and the sorted root-relative entries under it. The host walks the acquired source with no domain knowledge and reads no file content — it lists names only. The guest applies its own resolution logic over the listing (locating a chart root, selecting a single compose document, vendoring a module tree) and asks the host to pack a chosen selection through the pack-source host function. Entries are sorted by path so the listing is byte-identical across runs of identical input.
type SourceListing struct {
	// Root The acquired source location the host enumerated. The guest carries it into its own diagnostics when it cannot resolve the source, so a resolution halt names the source the author supplied.
	Root string `json:"root" yaml:"root" cbor:"root"`
	// RootIsDir Whether the acquired source root is a directory. False for a single-file source (a lone compose document, a single module file, an archive), in which case entries is empty and the guest packs the root itself.
	RootIsDir bool `json:"root_is_dir,omitempty" yaml:"root_is_dir,omitempty" cbor:"root_is_dir,omitempty"`
	// Entries The root-relative entries under a directory source root, sorted by path. Empty for a single-file source root.
	Entries []SourceEntry `json:"entries" yaml:"entries" cbor:"entries"`
}

// SourcePackRequest The selection a guest asks the host to pack from the acquired source through the pack-source host function. The op names the shape of the selection and the path names it relative to the source root; the host resolves the path under the source root, rejecting any escape above it, and returns the packed bytes as a SourceProjection.
type SourcePackRequest struct {
	// Op The selection shape: file packs the single file at path; dir packs the immediate files of the directory at path; tree packs the whole subtree rooted at path, recursively, in the host's deterministic walk order.
	Op string `json:"op" yaml:"op" cbor:"op"`
	// Path The selection location relative to the source root, slash-separated. The empty string (or ".") names the source root itself, so a single-file source is packed with an empty path.
	Path string `json:"path" yaml:"path" cbor:"path"`
}

// SourcePackResponse The pack-source host function's reply: on success the packed source, on failure an error message. Exactly one of the two fields is populated. Failure is delivered in-band rather than by trapping, so a guest carries a sandbox rejection or a read failure into its own diagnostics as a deterministic render failure.
type SourcePackResponse struct {
	// SourceProjection The packed source on success; absent on failure.
	SourceProjection *SourceProjection `json:"source_projection,omitempty" yaml:"source_projection,omitempty" cbor:"source_projection,omitempty"`
	// Error The failure message on failure, naming the selection and the reason; absent on success.
	Error string `json:"error,omitempty" yaml:"error,omitempty" cbor:"error,omitempty"`
	// HostfuncErrorCode The machine-matchable failure identity on failure, drawn from the closed host-function error-code catalog, set beside the human error message; absent on success. That catalog is a fixed vocabulary naming the ways a host function can fail, and it is a different vocabulary from the halting conditions the compiler registers, whose identifiers a guest reports on a socket output as condition_code and condition_short_code — the key name says which of the two a value belongs to, so the two are never read as one set. A guest branches on this code without parsing the message, tolerating an absent code (older host) or an unrecognized one (newer host) by falling back to the message.
	HostfuncErrorCode string `json:"hostfunc_error_code,omitempty" yaml:"hostfunc_error_code,omitempty" cbor:"hostfunc_error_code,omitempty"`
}

// SourceFileRequest The single-file content read a guest asks the host to perform through the read-source-file host function, for a guest whose resolution logic must inspect a file's content before choosing what to pack. The host resolves the path under the source root, rejecting any escape above it, and returns the file's bytes.
type SourceFileRequest struct {
	// Path The file location relative to the source root, slash-separated.
	Path string `json:"path" yaml:"path" cbor:"path"`
}

// SourceFileResponse The read-source-file host function's reply: on success the file's bytes, on failure an error message. Exactly one of the two fields is populated. Failure is delivered in-band rather than by trapping, so a guest carries a sandbox rejection or a read failure into its own diagnostics as a deterministic render failure.
type SourceFileResponse struct {
	// Content The file's raw bytes on success; absent on failure. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
	Content []byte `json:"content,omitempty" yaml:"content,omitempty" cbor:"content,omitempty"`
	// Error The failure message on failure, naming the file and the reason; absent on success.
	Error string `json:"error,omitempty" yaml:"error,omitempty" cbor:"error,omitempty"`
	// HostfuncErrorCode The machine-matchable failure identity on failure, drawn from the closed host-function error-code catalog, set beside the human error message; absent on success. That catalog is a fixed vocabulary naming the ways a host function can fail, and it is a different vocabulary from the halting conditions the compiler registers, whose identifiers a guest reports on a socket output as condition_code and condition_short_code — the key name says which of the two a value belongs to, so the two are never read as one set. A guest branches on this code without parsing the message, tolerating an absent code (older host) or an unrecognized one (newer host) by falling back to the message.
	HostfuncErrorCode string `json:"hostfunc_error_code,omitempty" yaml:"hostfunc_error_code,omitempty" cbor:"hostfunc_error_code,omitempty"`
}

// FetchExternalInputResponse The fetch-external-input host function's reply: on success the fetched content, on failure an error message and its code. A reply that carries neither failure field is a success, so a zero-length payload is the reply with every field absent. Failure is delivered in-band rather than by trapping, so a guest carries an unresolvable URL or a fetch failure into its own diagnostics as a deterministic render failure. The request is a bare URL string rather than a structured payload, so only the reply has a declared shape.
type FetchExternalInputResponse struct {
	// Content The fetched payload's raw bytes on success; absent on failure, and absent when the payload is empty. The bytes cross the wire as a byte string, never as base64 text. The Go kit holds them as a byte slice; the Rust and TypeScript kits hold them as a base64 string, which each kit's fetch wrapper decodes, so every wrapper returns the payload's raw bytes.
	Content []byte `json:"content,omitempty" yaml:"content,omitempty" cbor:"content,omitempty"`
	// Error The failure message on failure, naming the URL and the remedy; absent on success.
	Error string `json:"error,omitempty" yaml:"error,omitempty" cbor:"error,omitempty"`
	// HostfuncErrorCode The machine-matchable failure identity on failure, drawn from the closed host-function error-code catalog, set beside the human error message; absent on success. That catalog is a fixed vocabulary naming the ways a host function can fail, and it is a different vocabulary from the halting conditions the compiler registers, whose identifiers a guest reports on a socket output as condition_code and condition_short_code — the key name says which of the two a value belongs to, so the two are never read as one set. A guest branches on this code without parsing the message, tolerating an absent code (older host) or an unrecognized one (newer host) by falling back to the message.
	HostfuncErrorCode string `json:"hostfunc_error_code,omitempty" yaml:"hostfunc_error_code,omitempty" cbor:"hostfunc_error_code,omitempty"`
}

// WorkloadProjection The pre-evaluated workload content the host hands a Provider guest so the guest synthesizes provider-native manifests from it in memory, present when the bound Recipe declares a workload rather than a chart source. Determinism is the guest's responsibility: identical input must produce identical bytes.
type WorkloadProjection struct {
	// Workload The host-evaluated, post-validation Workload the guest synthesizes; opaque at this schema layer so the socket schema does not rebind the Workload entity contract.
	Workload types.Workload `json:"workload" yaml:"workload" cbor:"workload"`
	// SensitiveWorkload True when the template that produced workload reads a value an author declared sensitive, or a value traced to one. It is read from the template's own references against the declarations — a reference reaching a declared value, the template handing on the whole of its data, or a template that does not parse all count — and never from the content of any field. A rendered workload's fields carry no link back to the data its template read, so this marks the whole document: a guest composing text a person reads, a refusal or a warning, keeps every value the workload carries out of that text when this is true, while the document's shape — its keys and where a value sits — stays readable. The attachment entries the node projection's sensitive_rendered_keys names are marked there whether or not this is set. Absent when the template reads no such value; absence never states that no field is sensitive.
	SensitiveWorkload bool `json:"sensitive_workload,omitempty" yaml:"sensitive_workload,omitempty" cbor:"sensitive_workload,omitempty"`
	// AttachmentProvides Every attachment on the node, projected to its resolved provides and keyed by the attachment instance name a workload attachment reference carries; absent when the node carries no attachments. The host copies the strings through without interpreting them, so the guest reads whichever entries of an attachment's provides it needs to resolve a reference to the resource that attachment produced. Whether an attachment handles declared-sensitive material is not repeated here: it travels on the node projection's matching feature entry, which a guest reads by the same instance name.
	AttachmentProvides map[string]types.OrderedMap[string] `json:"attachment_provides,omitempty" yaml:"attachment_provides,omitempty" cbor:"attachment_provides,omitempty"`
}

// ArtifactsProjection The pre-evaluated artifact set the host hands a Provider guest to place into the node's output. The host has already resolved each entry's source (inline content or an imported file it read), evaluated it as a Go template against the render context using the guest's declared artifact-template delimiter pair, and computed the build-provenance label and annotation key sets. The guest owns the format decision, the provenance placement, the on-disk path, and the final bytes. Entries preserve author order so the placed output is byte-identical across runs of identical input.
type ArtifactsProjection struct {
	// Entries The artifact entries the guest places, in author order.
	Entries []ArtifactProjectionEntry `json:"entries" yaml:"entries" cbor:"entries"`
}

// ArtifactProjectionEntry One pre-evaluated artifact entry the host hands a Provider guest to place: its host-resolved output name, its origin, the already-template-evaluated content bytes, whether the template those bytes came from reads a value declared sensitive, and the build-provenance label and annotation key sets the host computed for the node. The guest decides how to place the provenance (splicing it into a manifest's metadata, prepending it as a comment, or emitting a companion file) and where the file lands.
type ArtifactProjectionEntry struct {
	// Name The host-resolved output name for the entry: the author-declared map key, with a file supplied by a library bundle nested under that key. The guest places the entry at this name or under a provider-specific sub-path derived from it.
	Name string `json:"name" yaml:"name" cbor:"name"`
	// Origin Whether the entry was authored as inline content or as an imported file. A guest that rejects one form (an umbrella-chart provider rejects inline content) reads this to halt loudly.
	Origin string `json:"origin" yaml:"origin" cbor:"origin"`
	// Content The already-template-evaluated content bytes the host produced from the entry's inline content or imported file, evaluated against the render context using the guest's declared artifact-template delimiter pair. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
	Content []byte `json:"content" yaml:"content" cbor:"content"`
	// SensitiveContent True when the template this entry's content was evaluated from reads a value an author declared sensitive, or a value traced to one. It is read from the template's own references against the declarations, with the delimiter pair the content was evaluated with — a reference reaching a declared value, the template handing on the whole of its data, or a template that does not parse all count — and never from the content itself. The content is that template's output, so nothing in it can be traced back to the datum it came from: a guest composing text a person reads, a refusal or a warning, keeps every part of the content out of that text when this is true, a parser's own message about the content included. It is set per entry, so one entry's template reading such a value says nothing about another's. Absent when the template reads no such value; absence never states that the content is not sensitive.
	SensitiveContent bool `json:"sensitive_content,omitempty" yaml:"sensitive_content,omitempty" cbor:"sensitive_content,omitempty"`
	// Labels The Kubernetes-label-safe build-provenance key set the host computed for the node, keyed by label name. A guest that stamps provenance into a manifest's metadata.labels splices these; a guest whose output is not Kubernetes YAML ignores them.
	Labels map[string]string `json:"labels,omitempty" yaml:"labels,omitempty" cbor:"labels,omitempty"`
	// Annotations The build-provenance key set the host computed for the node that a Kubernetes label cannot represent, keyed by annotation name. A guest that stamps provenance into a manifest's metadata.annotations splices these; a guest whose output is not Kubernetes YAML ignores them.
	Annotations map[string]string `json:"annotations,omitempty" yaml:"annotations,omitempty" cbor:"annotations,omitempty"`
}

// AssembleBoundaryInput The payload a Provider guest receives on its assemble_boundary export — the export that merges the per-node render outputs at one dispatch group into a single assembled artifact (an umbrella chart, a merged compose file). It carries the per-node render outputs with their merged annotations and deployment waves, the dispatch-group output path the assembled artifact lands at, the graph's uses edges for per-service dependency inference, and the render-time context. Not every provider declares the export: providers that emit only flat per-node output omit it.
type AssembleBoundaryInput struct {
	// Boundary Optional per-render boundary metadata a guest may consult. A dispatch group can merge contributors from multiple boundaries, so there is no single boundary; the field is carry-only-consumed and absent when the host merges across boundaries. Opaque at this schema layer; the guest reads the boundary-context shape through the render-context wire contract.
	Boundary renderctx.BoundaryContext `json:"boundary,omitempty" yaml:"boundary,omitempty" cbor:"boundary,omitempty"`
	// RenderedNodes The per-node render outputs that fed this dispatch group, in node order.
	RenderedNodes []RenderedNode `json:"rendered_nodes" yaml:"rendered_nodes" cbor:"rendered_nodes"`
	// Context The render-time context the host hands the guest, the same opaque render-context passthrough the render_node export receives.
	Context renderctx.RenderContext `json:"context" yaml:"context" cbor:"context"`
	// BoundaryPath The evaluated dispatch-group output path the assembled artifact lands at; a boundary assembler uses it as the boundary-level fallback identity (e.g. the compose network name for a node carrying no namespace annotation).
	BoundaryPath string `json:"boundary_path" yaml:"boundary_path" cbor:"boundary_path"`
	// Edges The graph's directed uses edges, so a boundary assembler can infer per-service ordering/dependencies across the dispatch group's contributors (e.g. compose depends_on).
	Edges []RenderEdge `json:"edges,omitempty" yaml:"edges,omitempty" cbor:"edges,omitempty"`
	// SubCharts The per-sub-chart payload an umbrella-chart assembler consumes to emit one dependency and one values scope per contributor. Each entry carries the sub-chart's identity, per-instance values, and, for a sub-chart vendored from a chart source, the pristine bytes of that chart's Chart.yaml file. Present for umbrella-chart assembly; a flat-merging assembler omits it.
	SubCharts []SubChart `json:"sub_charts,omitempty" yaml:"sub_charts,omitempty" cbor:"sub_charts,omitempty"`
	// ChartName The chart name an umbrella-chart assembler uses for the assembled chart when a name is supplied for the dispatch group; empty when the assembler derives the name from the dispatch-group output path.
	ChartName string `json:"chart_name,omitempty" yaml:"chart_name,omitempty" cbor:"chart_name,omitempty"`
	// AggregateName The top-level aggregate name an umbrella-chart assembler folds into the assembled chart's derived name; empty when no aggregate identity contributes to the name.
	AggregateName string `json:"aggregate_name,omitempty" yaml:"aggregate_name,omitempty" cbor:"aggregate_name,omitempty"`
}

// RenderedNode One node's render output as it appears in an assemble_boundary input: the node id, its type, its merged annotations, its sync wave, the values the compiler resolved for it where those are the compiler's to supply, and the files the render_node export produced for it — carried in the render output's shape, with every member of that shape other than its files left absent.
type RenderedNode struct {
	// ID The node's absolute id within the topology graph. A contributor that is not one of the graph's nodes — a Feature attached at a boundary rather than at a component — carries the compiler's own dispatch identity for it here instead, which is the same identity the render_node call for that contributor carried; it distinguishes one contributor from another and is not a name any target accepts. What such a contributor derives names from inside the assembled artifact is a separate carry, derived_name_basis.
	ID string `json:"id" yaml:"id" cbor:"id"`
	// Type The node's component-type label, carried on this shape — unlike the per-node render projection, which withholds it. Opaque metadata rather than a behavior switch: it is here so an assembler can group and label the nodes it merges, not so a guest can branch on it.
	Type string `json:"type" yaml:"type" cbor:"type"`
	// DerivedNameBasis The identity this contributor derives its own names from inside the assembled artifact — a logical id an assembler mints for one of the contributor's published entries, a per-contributor scope in a merged document. Empty means the id is used directly, which is the value for an ordinary component. It is the same carry the render_node call for this contributor received, and carrying it on both is what keeps the two answers equal: a name the contributor declared while rendering and the name the assembled artifact ends up addressing that content by are derived from one identity rather than from two that happen to agree. A contributor whose id is a dispatch identity a target's name alphabet refuses carries this explicitly, so the assembled artifact addresses its content by a name the target accepts, and two contributors an author can tell apart cannot arrive under one.
	DerivedNameBasis string `json:"derived_name_basis,omitempty" yaml:"derived_name_basis,omitempty" cbor:"derived_name_basis,omitempty"`
	// OutputDirectory The directory this contributor's rendered files sit in, relative to the assembled artifact's own position, carrying no trailing separator. A guest that has to name a contributor's files from inside the assembled artifact — the source path of a module block, an include directive — reads the position from here rather than composing one from the contributor's identity, so the path the assembled artifact points at is the path the files were written to. The two are not always one directory apart: a contributor the host placed inside another contributor's position sits deeper than the contributors placed directly beneath the assembly. Present only where the assembling provider places each contributor under a position of its own; a provider that folds its contributors into one document places no per-contributor directory and receives none.
	OutputDirectory string           `json:"output_directory,omitempty" yaml:"output_directory,omitempty" cbor:"output_directory,omitempty"`
	Rendered        RenderNodeOutput `json:"rendered" yaml:"rendered" cbor:"rendered"`
	// Annotations The node's merged annotations, so a boundary assembler can attribute per-node placement (e.g. the compose network derived from the aggrega.ai/namespace annotation).
	Annotations types.OrderedMap[string] `json:"annotations,omitempty,omitzero" yaml:"annotations,omitempty" cbor:"annotations,omitempty"`
	// SyncWave The deployment wave this node inherited from its containing boundary (default 0; negative permitted), so a boundary assembler can order the contributors it merges relative to one another. A dispatch group can merge contributors from several boundaries, each carrying its own wave, so the wave travels with every node here rather than once for the whole payload. An assembler whose output shape expresses no ordering ignores it.
	SyncWave int `json:"sync_wave,omitempty" yaml:"sync_wave,omitempty" cbor:"sync_wave,omitempty"`
	// Values The values the compiler resolved for this node, present only for a node rendered from a source — the render_node call that produced its files carried a source_listing. That is the one case where the files came from elsewhere and the values could not be written into them, so a position outside them has to supply them: a boundary assembler places a present dictionary as that contributor's inputs in the assembled artifact itself, rather than beside the contributor's own files, and where the assembled artifact is the only position the target evaluates, that is the difference between an input the target reads and one it never reaches. A node rendered from a workload_projection or an artifacts_projection resolved these values into the files it produced, so it carries none here and the field is absent: supplying them a second time would offer the assembled artifact inputs that node's own files never declare, which the target is free to reject. Keys arrive in sorted order, not author order, and that sorting is what makes the payload byte-identical across runs of identical input; a guest needing any other ordering imposes it itself. An assembler whose output shape carries no per-contributor inputs ignores the field.
	Values types.OrderedMap[any] `json:"values,omitempty,omitzero" yaml:"values,omitempty" cbor:"values,omitempty"`
}

type RenderEdge struct {
	// Source The consuming node's id — the source end of a directed uses edge.
	Source string `json:"source" yaml:"source" cbor:"source"`
	// Target The consumed node's id — the target end a directed uses edge points at.
	Target string `json:"target" yaml:"target" cbor:"target"`
}

// SubChart One sub-chart contributing to an umbrella chart: its instance identity, the version the umbrella pins, the per-instance values the umbrella scopes under the sub-chart's alias, and, for a sub-chart vendored from a chart source, the pristine bytes of that chart's Chart.yaml file. An umbrella-chart assembler builds the umbrella's dependencies and values file from these pure-data views alone and touches no filesystem.
type SubChart struct {
	// InstanceID The sub-chart's instance identity within the dispatch group; the umbrella scopes the sub-chart's dependency alias and its values under it, so multiple instances of one source chart stay distinct.
	InstanceID string `json:"instance_id" yaml:"instance_id" cbor:"instance_id"`
	// Version The version the umbrella pins for the sub-chart. A sub-chart vendored from a chart source instead draws its dependency name and version from that chart's Chart.yaml file so the dependency binds; this value applies to a generative sub-chart that carries no vendored chart.
	Version string `json:"version,omitempty" yaml:"version,omitempty" cbor:"version,omitempty"`
	// Values The per-instance values the umbrella scopes under the sub-chart's alias in the umbrella values.yaml file. Keys arrive in sorted order, not author order, and that sorting is what makes the payload byte-identical across runs of identical input; a guest needing any other ordering imposes it itself.
	Values types.OrderedMap[any] `json:"values,omitempty,omitzero" yaml:"values,omitempty" cbor:"values,omitempty"`
	// ChartYaml The pristine bytes of the vendored chart's Chart.yaml, read from the local source at compile time, from which the umbrella draws the sub-chart dependency's name and version. Empty for a generative sub-chart that carries no vendored chart. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
	ChartYaml []byte `json:"chart_yaml,omitempty" yaml:"chart_yaml,omitempty" cbor:"chart_yaml,omitempty"`
}

// AssembleBoundaryOutput The payload a Provider guest returns from its assemble_boundary export: the serialized bytes of each assembled file and any diagnostics the guest raised while assembling. Where the assembled group's per-node files sit is not part of this reply — it is a static property of the provider, declared once on its describe() contract and in hand before any node renders. The guest returns each file's serialized bytes; the host writes them verbatim and runs no serializer. Determinism is the guest's responsibility: identical input must produce identical bytes.
type AssembleBoundaryOutput struct {
	// Files The assembled output files the guest emitted, in emission order. Each names its on-disk path and carries the serialized bytes the host writes verbatim.
	Files []RenderedFile `json:"files" yaml:"files" cbor:"files"`
	// Diagnostics Diagnostics the guest raised while assembling. Each element is the shared Wasm-plugin diagnostic shape.
	Diagnostics []renderctx.Diagnostic `json:"diagnostics,omitempty" yaml:"diagnostics,omitempty" cbor:"diagnostics,omitempty"`
	// Error A failure message set when the guest ran but could not complete the operation; absent on success. It is distinct from any diagnostics the output carries: diagnostics report issues found during a run that still produced a result, while error reports that the operation itself did not complete. The host surfaces a present error as a failed plugin invocation.
	Error string `json:"error,omitempty" yaml:"error,omitempty" cbor:"error,omitempty"`
	// ConditionCode The descriptive, machine-matchable identity of the condition the failure names — the code the condition is registered under, in the same open set the compiler registers its own halting conditions in, and not a member of the closed host-function error-code catalog a reply envelope's hostfunc_error_code draws from. Set beside the human error message; absent on success, and absent when the guest names no such condition. A guest that halts reports here the identifier of the condition its message names, so a consumer branches on it instead of recovering an identity by reading the message. The host resolves this identifier against the conditions the compiler declares and publishes the resolved condition's own identifiers on the structured diagnostic, so a code that reaches a reader always resolves; an identifier naming no such condition, or one the numbering has retired, halts the build. A guest with no precise condition to name reaches instead for one of the generic plugin-failure conditions the compiler declares for the purpose, and puts the specifics in its own message. This identifier and condition_short_code are reported together, because they name one condition in two forms: a guest that sets one and not the other has named a condition the host cannot resolve, and the host then reports its own generic plugin-failure condition instead while the message still carries the whole failure.
	ConditionCode string `json:"condition_code,omitempty" yaml:"condition_code,omitempty" cbor:"condition_code,omitempty"`
	// ConditionShortCode The compact identifier of the same condition — the letter E and four digits, the form a reader quotes, searches for and pastes into a report — set beside the human error message; absent on success, and absent when the guest names no such condition. The host prints it in the bracketed head of the diagnostic it renders for this failure, so a condition a guest raises is quotable exactly as one the compiler raises is. The host resolves the value against the conditions the compiler declares rather than carrying it on trust: a value naming no such condition, a value the numbering has retired, or a spelling the registration does not carry halts the build and quotes the offending value, with the guest's own message still reported. It is reported together with condition_code, for the reason stated there.
	ConditionShortCode string `json:"condition_short_code,omitempty" yaml:"condition_short_code,omitempty" cbor:"condition_short_code,omitempty"`
}

// CarveInput The payload a Provider guest receives on its optional carve export: one named output file the pipeline carves into addressable units before a FeatureRecipe step edits some of them. A provider whose output shape the stock YAML codec cannot carve directly (a templated chart, for instance) advertises carve and reassemble so its own output-shape knowledge lives in the guest; a provider that omits the exports borrows the host's stock YAML codec.
type CarveInput struct {
	// Name The output file's name, so the codec can apply any name-scoped carving rule.
	Name string `json:"name" yaml:"name" cbor:"name"`
	// Body The output file's bytes to carve into addressable units. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
	Body []byte `json:"body" yaml:"body" cbor:"body"`
	// YamlIndent The indentation width the codec uses when it must synthesize new structured text; carried so the guest's carving matches the render-wide indentation.
	YamlIndent int `json:"yaml_indent,omitempty" yaml:"yaml_indent,omitempty" cbor:"yaml_indent,omitempty"`
}

// CarveOutput The payload a Provider guest returns from its carve export: the ordered addressable units it carved the file into. A structured unit carries a tree (a PATCH target); an opaque unit carries only its media type and bytes.
type CarveOutput struct {
	// Units The ordered addressable units the guest carved the file into.
	Units []frp.Unit `json:"units" yaml:"units" cbor:"units"`
}

// ReassembleInput The payload a Provider guest receives on its optional reassemble export: the original file plus its carved units and the patched units a pipeline step produced, so the guest splices the changes back into the original bytes surgically. A token absent from the patched set is re-joined from its original bytes verbatim; a patched token has only its addressed byte-spans edited.
type ReassembleInput struct {
	// Name The output file's name, matching the name the same file was carved under.
	Name string `json:"name" yaml:"name" cbor:"name"`
	// Body The original file bytes the reassembly splices the patched units back into. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
	Body []byte `json:"body" yaml:"body" cbor:"body"`
	// Segs The units the file was carved into, as carve returned them.
	Segs []frp.Unit `json:"segs,omitempty" yaml:"segs,omitempty" cbor:"segs,omitempty"`
	// Patched The units a pipeline step changed, each carrying its token, patched tree, and the ops that produced the change.
	Patched []frp.PatchedUnit `json:"patched,omitempty" yaml:"patched,omitempty" cbor:"patched,omitempty"`
	// YamlIndent The indentation width the codec uses when an op must synthesize new structured text; carried so the reassembly matches the render-wide indentation.
	YamlIndent int `json:"yaml_indent,omitempty" yaml:"yaml_indent,omitempty" cbor:"yaml_indent,omitempty"`
}

// ReassembleOutput The payload a Provider guest returns from its reassemble export: the file's bytes with the patched units spliced back in. Reassembly is byte-faithful — every byte the ops did not touch survives verbatim.
type ReassembleOutput struct {
	// Body The reassembled file bytes the host writes verbatim. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
	Body []byte `json:"body" yaml:"body" cbor:"body"`
}

